('Noche de Malbecs Mendocinos', '2026-10-03', 'Degustacion guiada de 5 etiquetas seleccionadas de Lujan de Cuyo y Valle de Uco con tabla de quesos artesanales.', 35, TRUE),
('Cata a Ciegas: Tintos de Alta Gama', '2026-10-09', 'Desafio sensorial para descubrir varietales y terroirs sin ver la etiqueta, acompanado de bruschettas gourmet.', 25, TRUE),
('Maridaje de Primavera y Tapas', '2026-10-15', 'Recorrido gastronomico en 4 pasos armonizado con vinos blancos aromaticos y rosados frescos de cosecha reciente.', 40, TRUE),
('Especial Bodegas del Norte', '2026-10-21', 'Exploracion de vinos de altura de Salta y Cafayate, destacando Torrontes y Cabernet Sauvignon.', 30, TRUE),
('Noche de Espumantes y Quesos', '2026-10-25', 'Degustacion de metodos charmat y tradicional maridados con quesos blandos, semiduros y frutos secos.', 45, TRUE),
('Feria de Blancos y Rosados', '2026-10-30', 'Feria al aire libre ideal para la primavera, probando mas de 15 etiquetas de vinos blancos y rosados frescos.', 100, TRUE),
('Encuentro de Cabernets Argentinos', '2026-11-02', 'Comparativa entre Cabernet Sauvignon y Cabernet Franc de distintas regiones vitivinicolas del pais.', 32, TRUE),
